import * as React from "react";
import AppLink from "./AppLink";

type ProofHighlightItem = {
  eyebrow?: string;
  title: string;
  text: string;
  href?: string;
  ctaLabel?: string;
};

type ProofHighlightsProps = {
  title: string;
  subtitle?: string;
  items: ProofHighlightItem[];
};

const ProofHighlights: React.FC<ProofHighlightsProps> = ({
  title,
  subtitle,
  items,
}) => {
  if (!title || !Array.isArray(items) || items.length === 0) {
    return null;
  }

  return (
    <section className="py-10 sm:py-14">
      <div className="mx-auto w-full max-w-6xl px-4 sm:px-6">
        <div className="mx-auto max-w-4xl text-center">
          <h2 className="text-2xl sm:text-4xl poppins-regular text-verde">
            {title}
          </h2>
          {subtitle ? (
            <p className="mt-4 text-sm sm:text-base text-light/70">{subtitle}</p>
          ) : null}
        </div>

        <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-4">
          {items.map((item, index) => (
            <div
              key={`${item.title}-${index}`}
              className="rounded-2xl border border-black/10 bg-primary/70 p-5 shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur text-light"
            >
              {item.eyebrow ? (
                <p className="text-xs font-semibold uppercase tracking-[0.14em] text-secondary">
                  {item.eyebrow}
                </p>
              ) : null}
              <h3 className="mt-2 text-base sm:text-lg font-semibold text-light/90">
                {item.title}
              </h3>
              <p className="mt-3 text-sm sm:text-base text-light/70 leading-relaxed">
                {item.text}
              </p>
              {item.href && item.ctaLabel ? (
                <div className="mt-4">
                  <AppLink className="underline text-sm" to={item.href}>
                    {item.ctaLabel}
                  </AppLink>
                </div>
              ) : null}
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default ProofHighlights;
